<script setup lang="ts">
import { ref, watch } from 'vue';
import { useRoute, useRouter, RouterLink } from 'vue-router';
import axios from 'axios';
interface Product {id:number;title:string;description:string;price:number;location:string;imageUrl:string;status:string}
const route=useRoute(),router=useRouter();
const products=ref<Product[]>([]), product=ref<Product|null>(null),keyword=ref(''),total=ref(0),page=ref(1),loading=ref(false),error=ref('');
let request=0;
async function load(){const current=++request;loading.value=true;error.value='';product.value=null;try{
 if(route.params.id){const {data}=await axios.get<Product>('/api/products/'+route.params.id);if(current===request)product.value=data;}
 else{page.value=Number(route.query.page)||1;keyword.value=String(route.query.keyword||'');const {data}=await axios.get('/api/products',{params:{keyword:keyword.value,page:page.value,size:12}});if(current===request){products.value=data.items;total.value=data.total;}}
 }catch(e){if(current===request)error.value=axios.isAxiosError(e)&&e.response?.status===404?'这件商品不存在':'暂时无法加载，请稍后重试';}finally{if(current===request)loading.value=false;}}
function search(){router.push({path:'/market',query:keyword.value?{keyword:keyword.value}:{}});}
function changePage(n:number){router.push({path:'/market',query:{keyword:keyword.value,page:n}});}
watch(()=>route.fullPath,load,{immediate:true});
</script>
<template><section class="market"><div class="market-heading"><p>SDU / CAMPUS MARKET</p><h1>{{ route.params.id ? '好物详情' : '校园二手市场' }}</h1><span>让闲置流转，让校园生活多一份可能。</span></div>
<div class="market-body"><RouterLink v-if="route.params.id" to="/market" class="back-link">← 返回二手市场</RouterLink><form v-else class="search-form" @submit.prevent="search"><label for="search">寻找校园好物</label><div><input id="search" v-model="keyword" maxlength="100" placeholder="搜索商品名称或描述"><button>搜索</button></div></form>
<p v-if="loading" role="status">正在加载好物…</p><div v-else-if="error" role="alert"><p>{{ error }}</p><button @click="load">重新加载</button></div>
<article v-else-if="product" class="product-detail"><img :src="product.imageUrl" :alt="product.title"><div><span class="product-tag">校园闲置 · {{ product.status==='AVAILABLE'?'在售':'已下架' }}</span><h2>{{ product.title }}</h2><p class="price">¥ {{ Number(product.price).toFixed(2) }}</p><p class="location">交易地点：{{ product.location || '待补充' }}</p><h3>商品描述</h3><p class="description">{{ product.description || '卖家暂未填写描述' }}</p><p class="trade-note">交易功能尚未开放，当前可浏览商品信息。</p></div></article>
<template v-else><p class="results">共 {{ total }} 件好物</p><div v-if="products.length" class="product-grid"><RouterLink v-for="item in products" :key="item.id" :to="'/market/'+item.id" class="product-card"><div class="product-photo"><img :src="item.imageUrl" :alt="item.title" loading="lazy"></div><div class="product-info"><small>校园闲置</small><h2>{{ item.title }}</h2><p>{{ item.location || '地点待补充' }}</p><strong>¥ {{ Number(item.price).toFixed(2) }}</strong><span>查看详情 ↗</span></div></RouterLink></div><p v-else class="empty">暂时没有找到相关好物，换个关键词试试。</p><div v-if="total>12" class="pagination"><button :disabled="page<=1" @click="changePage(page-1)">上一页</button><span>{{ page }} / {{ Math.ceil(total/12) }}</span><button :disabled="page*12>=total" @click="changePage(page+1)">下一页</button></div></template></div></section></template>
<style scoped>
.market{flex:1;background:#f6f4ee;color:#293d3b}.market-heading{padding:45px 7%;background:linear-gradient(90deg,#172d3cda,#172d3c80),url('/assets/legacy/images/sdu.jpg') center 45%/cover;color:white}.market-heading>p{font-size:10px;letter-spacing:3px;color:#ecd2a9}.market-heading h1{font-size:34px;margin:14px 0;letter-spacing:2px}.market-heading>span{font-size:13px;color:#ffffffe0}.market-body{max-width:1200px;margin:auto;padding:36px 28px 60px}.search-form{display:flex;justify-content:space-between;align-items:center;gap:20px}.search-form label{font-size:20px;font-weight:600}.search-form>div{display:flex;width:min(480px,60%)}input{padding:13px;border:1px solid #d3d7cd;border-radius:4px 0 0 4px;min-width:0;flex:1;font:inherit;font-size:13px}button{background:#304b49;color:white;border:0;padding:12px 24px;border-radius:3px}button:disabled{opacity:.4;cursor:default}.results{font-size:12px;color:#6f7b70;margin:28px 0 18px}.product-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.product-card{display:block;text-decoration:none;color:inherit;background:white;border:1px solid #e5e7de;border-radius:8px;overflow:hidden;transition:transform .2s,box-shadow .2s}.product-card:hover{transform:translateY(-4px);box-shadow:0 12px 24px #293d3b12}.product-photo{height:235px;background:#ebece5;padding:16px}.product-photo img{width:100%;height:100%;object-fit:contain}.product-info{padding:22px}.product-info small,.product-tag{font-size:10px;color:#92724b;letter-spacing:1px}.product-info h2{font-size:18px;margin:12px 0;overflow-wrap:anywhere}.product-info p{font-size:12px;color:#7e887f}.product-info strong{font-size:21px;color:#a44e36}.product-info>span{float:right;font-size:11px;color:#6e7f74;margin-top:8px}.back-link{color:#516b62;text-decoration:none;font-size:13px;display:inline-block;margin-bottom:25px}.product-detail{display:grid;grid-template-columns:1fr 1fr;gap:45px;background:white;padding:35px;border-radius:8px}.product-detail>img{width:100%;max-height:500px;object-fit:contain;background:#f1f1ec}.product-detail h2{font-size:28px;overflow-wrap:anywhere}.price{font-size:30px;color:#a44e36}.location{font-size:13px;color:#7e887f;border-bottom:1px solid #e5e7de;padding-bottom:20px}.product-detail h3{font-size:15px}.description{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9;font-size:14px;max-height:400px;overflow:auto}.trade-note{font-size:12px;background:#f8f4e9;color:#8c7450;padding:14px;line-height:1.8}.pagination{display:flex;justify-content:center;align-items:center;gap:20px;margin-top:35px}.empty{padding:60px;text-align:center;color:#778577}@media(max-width:850px){.product-grid{grid-template-columns:repeat(2,1fr)}.product-detail{grid-template-columns:1fr;padding:20px;gap:20px}.search-form{align-items:flex-start;flex-direction:column}.search-form>div{width:100%}}@media(max-width:500px){.product-grid{grid-template-columns:1fr}.market-body{padding:25px 20px}.product-photo{height:260px}}
</style>
